343: function applyMove(attacker, defender, move, done) {
344:   if(!battle||battle.finished)return
345:   if(move.type==='defend') {
346:     battle.guard[attacker]=true; battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+Math.abs(move.cost));
347:     toast(`${battle[attacker].name} braces and recovers stamina.`); done(); return
348:   }
349:   const cost=Math.max(0,move.cost)
350:   if(battle.sta[attacker]<cost) { battle.sta[attacker]=Math.min(battle.maxSta[attacker],battle.sta[attacker]+12); toast(`${battle[attacker].name} is winded and recovers 12 stamina.`); done(); return }
351:   battle.sta[attacker]-=cost
352:   if(Math.random()>move.acc) { toast(`${move.name} missed!`); done(); return }
353:   let damage=Math.round((10+move.power*16)*(0.78+statsOf(battle[attacker]).power/180)*(0.82+Math.random()*.36))
354:   if(move.crit&&Math.random()<move.crit)damage=Math.round(damage*1.5)
355:   if(battle.guard[defender]&&!move.pierce){damage=Math.ceil(damage*.48);battle.guard[defender]=false;toast(`${battle[defender].name} guarded the hit!`)}
356:   battle.hp[defender]=Math.max(0,battle.hp[defender]-damage)
357:   const defenderSide=attacker==='player'?'foe':'player'
358:   world.battleLunge(attacker,()=>world.hitReact(defenderSide,done))
359:   world.burst?.({x:attacker==='player'?2: -2,y:1.5,z:.3},phenotype(battle[attacker].genome).accentColor,15)
360:   toast(`${move.name} dealt ${damage} damage.`)
361:   if(move.buff==='evade')battle.guard[attacker]=true
362: }
